INTS = {'count', 'km', 'liters'}
LOCALES = {'en': 0, 'de': 1, 'fr': 2}

here = os.path.dirname(os.path.abspath(__file__))
out = os.path.join(here, '..', 'lib', 'l10n')
for locale, index in LOCALES.items():
    arb = {'@@locale': locale}
    for key, texts in S.items():
        arb[key] = texts[index]
        if locale == 'en':
            names = sorted(set(re.findall(r'\{(\w+)[,}]', texts[0])))
            if names:
                arb['@' + key] = {'placeholders': {
                    n: {'type': 'int' if n in INTS else 'String'} for n in names}}
    with open(os.path.join(out, f'app_{locale}.arb'), 'w', encoding='utf-8') as f:
        json.dump(arb, f, ensure_ascii=False, indent=2)
        f.write('\n')
print(len(S), 'texts')
